(3,'8c716f63-4802-4eff-85ca-d8157da5c13a','{\n  \"name\": \"Mental Health Assessment Form\",\n  \"version\": \"1\",\n  \"published\": true,\n  \"retired\": false,\n  \"pages\": [\n    {\n      \"label\": \"PHQ-2 Screening\",\n      \"sections\": [\n        {\n          \"label\": \"Introduction\",\n          \"isExpanded\": true,\n          \"questions\": [\n            {\n              \"type\": \"markdown\",\n              \"questionOptions\": {\n                \"rendering\": \"markdown\"\n              },\n              \"id\": \"phq9Intro\",\n              \"value\": [\n                \"**PHQ-9 Depression Screening**\",\n                \"\",\n                \"This form is used for screening, diagnosing, monitoring and measuring the severity of depression.\",\n                \"\",\n                \"**Instructions:** Over the last 2 weeks, how often have you been bothered by any of the following problems?\"\n              ]\n            }\n          ]\n        },\n        {\n          \"label\": \"Patient Health Questionnaire-2 (PHQ-2)\",\n          \"isExpanded\": true,\n          \"questions\": [\n            {\n              \"label\": \"Screening Date\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"date\",\n                \"concept\": \"160753AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"160753\"\n                  },\n                  {\n                    \"type\": \"SNOMED-CT\",\n                    \"value\": \"439771001\"\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\",\n                  \"validators\": [\n                    {\n                      \"type\": \"date\",\n                      \"allowFutureDates\": \"false\"\n                    },\n                    {\n                      \"type\": \"js_expression\",\n                      \"failsWhenExpression\": \"isDateBefore(myValue, \'1980-01-01\')\"\n                    }\n                  ]\n                }\n              ],\n              \"id\": \"phq9Date\"\n            },\n            {\n              \"label\": \"1. Little interest or pleasure in doing things\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"167006AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"167006\"\n                  },\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"44250-9\"\n                  }\n                ],\n                \"answers\": [\n                  {\n                    \"concept\": \"160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not at all\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167000AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Several days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167001AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"More than half the days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167002AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Nearly every day\",\n                    \"conceptMappings\": []\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\"\n                }\n              ],\n              \"id\": \"phq2_1\"\n            },\n            {\n              \"label\": \"2. Feeling down, depressed or hopeless\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"167007AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"167007\"\n                  },\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"44255-8\"\n                  }\n                ],\n                \"answers\": [\n                  {\n                    \"concept\": \"160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not at all\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167000AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Several days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167001AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"More than half the days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167002AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Nearly every day\",\n                    \"conceptMappings\": []\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\"\n                }\n              ],\n              \"id\": \"phq2_2\"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"PHQ-9 Additional Questions\",\n      \"sections\": [\n        {\n          \"label\": \"Further evaluation\",\n          \"isExpanded\": true,\n          \"questions\": [\n            {\n              \"label\": \"3. Trouble falling asleep, staying asleep, or sleeping too much\",\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"167068AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                \"conceptMappings\": [\n                  {\n                    \"type\": \"LOINC\",\n                    \"value\": \"44259-0\"\n                  },\n                  {\n                    \"type\": \"CIEL\",\n                    \"value\": \"167068\"\n                  }\n                ],\n                \"answers\": [\n                  {\n                    \"concept\": \"160215AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not at all\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167000AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Several days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167001AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"More than half the days\",\n                    \"conceptMappings\": []\n                  },\n                  {\n                    \"concept\": \"167002AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Nearly every day\",\n                    \"conceptMappings\": []\n                  }\n                ]\n              },\n              \"behaviours\": [\n                {\n                  \"intent\": \"*\",\n                  \"required\": \"true\",\n                  \"unspecified\": \"true\"\n                }\n              ],\n              \"id\": \"phq9_3\"\n         