(1213,2590,'Congenital structural deformities of the upper and lower extremities collectively or unspecified.','en',2,'2026-08-11 20:23:51',NULL,NULL,'5911FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1214,2593,'Alterations or deviations from normal shape or size which result in a disfigurement of the hand occurring at or before birth.','en',2,'2026-08-11 20:23:51',NULL,NULL,'5903FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
