('bahmni.appointments.runningOnOpenMRS',NULL,'If set to yes, the appointments ui will run independent of bahmni core','0d35a07e-95c2-11f1-b20b-0242ac170002',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('bahmni.sqlGet.pastAppointments','SELECT\n     app_service.name                                                                                           AS `DASHBOARD_APPOINTMENTS_SERVICE_KEY`,\n     app_service_type.name                                                                                      AS `DASHBOARD_APPOINTMENTS_SERVICE_TYPE_KEY`,\n     DATE_FORMAT(pa.start_date_time, \"%d/%m/%Y\")                                                                AS `DASHBOARD_APPOINTMENTS_DATE_KEY`,\n     CONCAT(DATE_FORMAT(pa.start_date_time, \"%l:%i %p\"), \" - \", DATE_FORMAT(pa.end_date_time, \"%l:%i %p\"))      AS `DASHBOARD_APPOINTMENTS_SLOT_KEY`,\n     CONCAT(pn.given_name, \" \", pn.family_name)                                                                 AS `DASHBOARD_APPOINTMENTS_PROVIDER_KEY`,\n     pa.status                                                                                                  AS `DASHBOARD_APPOINTMENTS_STATUS_KEY`,\n     CONVERT_TZ(pa.start_date_time,  @@session.time_zone, \"UTC\")                                                AS `DASHBOARD_APPOINTMENTS_START_DATE_IN_UTC_KEY`,\n     CONVERT_TZ(pa.end_date_time, @@session.time_zone, \"UTC\")                                                   AS `DASHBOARD_APPOINTMENTS_END_DATE_IN_UTC_KEY`\nFROM\npatient_appointment pa\nJOIN person p ON p.person_id = pa.patient_id AND pa.voided IS FALSE\nJOIN appointment_service app_service\n ON app_service.appointment_service_id = pa.appointment_service_id AND app_service.voided IS FALSE\nLEFT JOIN patient_appointment_provider pap on pa.patient_appointment_id = pap.patient_appointment_id AND (pap.voided=0 OR pap.voided IS NULL)\nLEFT JOIN provider prov ON prov.provider_id = pap.provider_id AND prov.retired IS FALSE\nLEFT JOIN person_name pn ON pn.person_id = prov.person_id AND pn.voided IS FALSE\nLEFT JOIN appointment_service_type app_service_type\n ON app_service_type.appointment_service_type_id = pa.appointment_service_type_id\nWHERE p.uuid = ${patientUuid} AND pa.start_date_time < CURDATE() AND (app_service_type.voided IS FALSE OR app_service_type.voided IS NULL)\nORDER BY pa.start_date_time DESC\nLIMIT 5;','Past appointments for patient','0d2ae3e5-95c2-11f1-b20b-0242ac170002',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('bahmni.sqlGet.upComingAppointments','SELECT\n  pa.uuid,\n  app_service.name                                                                                      AS `DASHBOARD_APPOINTMENTS_SERVICE_KEY`,\n  app_service_type.name                                                                                 AS `DASHBOARD_APPOINTMENTS_SERVICE_TYPE_KEY`,\n  DATE_FORMAT(pa.start_date_time, \"%d/%m/%Y\")                                                           AS `DASHBOARD_APPOINTMENTS_DATE_KEY`,\n  CONCAT(DATE_FORMAT(pa.start_date_time, \"%l:%i %p\"), \" - \", DATE_FORMAT(pa.end_date_time, \"%l:%i %p\")) AS `DASHBOARD_APPOINTMENTS_SLOT_KEY`,\n  CONCAT(pn.given_name, \" \", pn.family_name)                                                            AS `DASHBOARD_APPOINTMENTS_PROVIDER_KEY`,\n  CONVERT_TZ(pa.start_date_time, @@session.time_zone, \"UTC\")                                            AS `DASHBOARD_APPOINTMENTS_START_DATE_IN_UTC_KEY`,\n  CONVERT_TZ(pa.end_date_time, @@session.time_zone, \"UTC\")                                              AS `DASHBOARD_APPOINTMENTS_END_DATE_IN_UTC_KEY`,\n  pa.status                                                                                             AS `DASHBOARD_APPOINTMENTS_STATUS_KEY`,\n  pa.appointment_kind                                                                                   AS `DASHBOARD_APPOINTMENTS_KIND`,\n  pa.start_date_time                                                                                    AS `DASHBOARD_APPOINTMENTS_START_DATE_KEY`,\n  pa.end_date_time                                                                                      AS `DASHBOARD_APPOINTMENTS_END_DATE_KEY`,\n  pa.tele_health_video_link\nFROM\n  patient_appointment pa\n  JOIN person p ON p.person_id = pa.patient_id AND pa.voided IS FALSE\n  JOIN appointment_service app_service\n    ON app_service.appointment_service_id = pa.appointment_service_id AND app_service.voided IS FALSE\n  LEFT JOIN patient_appointment_provider pap on pa.patient_appointment_id = pap.patient_appointment_id AND (pap.voided=0 OR pap.voided IS NULL)\n  LEFT JOIN provider prov ON prov.provider_id = pap.provider_id AND prov.retired IS FALSE\n  LEFT JOIN person_name pn ON pn.person_id = prov.person_id AND pn.voided IS FALSE\n  LEFT JOIN appointment_service_type app_service_type\n    ON app_service_type.appointment_service_type_id = pa.appointment_service_type_id\nWHERE p.uuid = ${patientUuid} AND\n      pa.start_date_time >= CURDATE() AND\n      (app_service_type.voided IS FALSE OR app_service_type.voided IS NULL)\nORDER BY pa.start_date_time ASC;','Upcoming appointments for patient','0d2f2673-95c2-11f1-b20b-0242ac170002',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('bedmanagement.mandatory','false','true/false whether or not the bedmanagement module MUST start when openmrs starts.  This is used to make sure that mission critical modules are always running if openmrs is running.','4a80a54e-5e01-4d17-9197-f9d457bfbd79',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('bedManagement.sqlGet.patientListForAdmissionLocation','SELECT\n                    bed.bed_number AS \'Bed Number\',\n                    bed_tags.bed_tags AS \'Bed Tags\',\n                    bed.status as \'Bed Status\',\n                    patient_identifier.identifier AS \'Patient ID\',\n                    CONCAT(pn.given_name, \' \', pn.family_name)  AS \'Patient Name\',\n                    TIMESTAMPDIFF(YEAR, p.birthdate, CURDATE()) AS \'Age\'\n                FROM bed\n                    INNER JOIN bed_location_map blm ON blm.bed_id = bed.bed_id\n                    INNER JOIN location l ON l.location_id = blm.location_id AND l.retired IS FALSE\n                    LEFT OUTER JOIN bed_patient_assignment_map bpam ON bpam.bed_id = bed.bed_id AND bpam.date_stopped IS NULL\n                    LEFT OUTER JOIN person p ON p.person_id = bpam.patient_id AND p.voided IS FALSE\n                    LEFT OUTER JOIN person_name pn ON pn.person_id = p.person_id AND pn.voided IS FALSE\n                    LEFT OUTER JOIN patient_identifier ON patient_identifier.patient_id = p.person_id AND patient_identifier.voided IS FALSE\n                    LEFT OUTER JOIN person_address address ON address.person_id = p.person_id AND address.voided IS FALSE\n                    LEFT OUTER JOIN (\n                        SELECT bed_tag_map.bed_id AS \'bed_id\', GROUP_CONCAT(DISTINCT bed_tag.name ORDER BY bed_tag.name) AS \'bed_tags\'\n                        FROM bed_tag_map\n                        INNER JOIN bed_tag ON bed_tag.bed_tag_id = bed_tag_map.bed_tag_id AND bed_tag_map.voided IS FALSE\n                        GROUP BY bed_tag_map.bed_id\n                    ) bed_tags ON bed_tags.bed_id = bed.bed_id\n                WHERE l.name = ${location_name}\n                GROUP BY bed.bed_number;','Sql query to get admitted patients details in an Admission Location','0af6d99c-95c2-11f1-b20b-0242ac170002',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
